package com.company.platform.aigateway.application;import java.util.*;import org.springframework.stereotype.Component;@Component public class PromptRegistry{private final Map<String,Map<Integer,Map<String,Object>>> prompts=new HashMap<>();public Map<String,Object> register(String key,int version,String classification){if(key==null||key.isBlank()||version<1)throw new IllegalArgumentException("invalid prompt");prompts.computeIfAbsent(key,k->new HashMap<>()).put(version,Map.of("key",key,"version",version,"classification",classification,"enabled",true));return prompts.get(key).get(version);}public List<Map<String,Object>> list(){return prompts.values().stream().flatMap(x->x.values().stream()).toList();}}
